const KEY_MAP = {
  KeyW: 'throttleUp',
  KeyS: 'throttleDown',
  KeyA: 'rollLeft',
  KeyD: 'rollRight',
  ArrowUp: 'pitchUp',
  ArrowDown: 'pitchDown',
  ArrowLeft: 'yawLeft',
  ArrowRight: 'yawRight',
};

export function createControls({
  onToggleCamera,
  onReset,
  onToggleHud,
  onToggleMarkers,
  onTogglePause,
  onToggleBoost,
  onToggleAircraft,
  onFire,
} = {}) {
  const input = {
    throttleUp: false,
    throttleDown: false,
    rollLeft: false,
    rollRight: false,
    pitchUp: false,
    pitchDown: false,
    yawLeft: false,
    yawRight: false,
  };

  function keydown(e) {
    if (KEY_MAP[e.code]) {
      input[KEY_MAP[e.code]] = true;
      e.preventDefault();
      return;
    }
    if (e.repeat) return;
    switch (e.code) {
      case 'KeyF':
        onToggleCamera && onToggleCamera();
        break;
      case 'KeyR':
        onReset && onReset();
        break;
      case 'KeyH':
        onToggleHud && onToggleHud();
        break;
      case 'KeyM':
        onToggleMarkers && onToggleMarkers();
        break;
      case 'KeyP':
        onTogglePause && onTogglePause();
        break;
      case 'KeyB':
      case 'Space':
        onToggleBoost && onToggleBoost();
        break;
      case 'KeyG':
        onToggleAircraft && onToggleAircraft();
        break;
      case 'KeyV':
        onFire && onFire();
        break;
      default:
        return;
    }
    e.preventDefault();
  }

  function keyup(e) {
    if (KEY_MAP[e.code]) {
      input[KEY_MAP[e.code]] = false;
      e.preventDefault();
    }
  }

  window.addEventListener('keydown', keydown);
  window.addEventListener('keyup', keyup);
  window.addEventListener('blur', () => {
    for (const k of Object.keys(input)) input[k] = false;
  });

  return { input };
}

import * as THREE from 'three';
import { mulberry32 } from './noise.js';

export function buildWarpEffect(scene) {
  const rng = mulberry32(711967);
  const count = 180;
  const positions = new Float32Array(count * 6);
  const speeds = new Float32Array(count);
  const radii = new Float32Array(count);
  const angles = new Float32Array(count);

  for (let i = 0; i < count; i++) {
    radii[i] = 5 + Math.pow(rng(), 0.6) * 52;
    angles[i] = rng() * Math.PI * 2;
    speeds[i] = 0.75 + rng() * 1.45;
    const z = -180 + rng() * 260;
    const x = Math.cos(angles[i]) * radii[i];
    const y = Math.sin(angles[i]) * radii[i] * 0.58;
    const o = i * 6;
    positions.set([x, y, z, x, y, z + 4], o);
  }

  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const mat = new THREE.LineBasicMaterial({
    color: '#a8e9ff', transparent: true, opacity: 0, blending: THREE.AdditiveBlending,
    depthWrite: false, toneMapped: false,
  });
  const lines = new THREE.LineSegments(geo, mat);
  lines.frustumCulled = false;
  lines.renderOrder = 30;
  lines.visible = false;
  scene.add(lines);

  return { lines, positions, speeds, radii, angles, intensity: 0 };
}

export function updateWarpEffect(effect, aircraft, active, speed, dt) {
  effect.intensity += ((active ? 1 : 0) - effect.intensity) * Math.min(1, dt * (active ? 8 : 4));
  effect.lines.visible = effect.intensity > 0.015;
  effect.lines.material.opacity = effect.intensity * 0.74;
  effect.lines.position.copy(aircraft.position);
  effect.lines.quaternion.copy(aircraft.quaternion);

  const travel = Math.max(40, speed) * dt * 1.65;
  const length = 3 + effect.intensity * 28;
  for (let i = 0; i < effect.speeds.length; i++) {
    const o = i * 6;
    let z = effect.positions[o + 2] + travel * effect.speeds[i];
    if (z > 92) z -= 280;
    const x = Math.cos(effect.angles[i]) * effect.radii[i];
    const y = Math.sin(effect.angles[i]) * effect.radii[i] * 0.58;
    effect.positions[o] = effect.positions[o + 3] = x;
    effect.positions[o + 1] = effect.positions[o + 4] = y;
    effect.positions[o + 2] = z;
    effect.positions[o + 5] = z + length * effect.speeds[i];
  }
  effect.lines.geometry.attributes.position.needsUpdate = true;
}

const MS_TO_KT = 1.94384;
const M_TO_FT = 3.28084;

function headingLabel(rad) {
  let deg = (rad * 180) / Math.PI;
  deg = ((deg % 360) + 360) % 360;
  const dirs = ['N', 'NNE', 'NE', 'ENE', 'E', 'ESE', 'SE', 'SSE', 'S', 'SSW', 'SW', 'WSW', 'W', 'WNW', 'NW', 'NNW'];
  const idx = Math.round(deg / 22.5) % 16;
  return { deg: Math.round(deg), dir: dirs[idx] };
}

export function createHud(markers) {
  const root = document.getElementById('hud');
  const els = {
    altitude: document.getElementById('hud-altitude'),
    speed: document.getElementById('hud-speed'),
    heading: document.getElementById('hud-heading'),
    throttle: document.getElementById('hud-throttle'),
    distance: document.getElementById('hud-distance'),
    checklist: document.getElementById('hud-checklist'),
    toast: document.getElementById('hud-toast'),
    pause: document.getElementById('hud-pause'),
    progress: document.getElementById('hud-progress'),
    aircraft: document.getElementById('hud-aircraft'),
    boost: document.getElementById('hud-boost'),
  };

  els.checklist.innerHTML = '';
  const rows = {};
  for (const m of markers) {
    const row = document.createElement('div');
    row.className = 'checklist-row' + (m.primary ? ' primary' : '');
    row.innerHTML = `<span class="dot"></span><span class="name">${m.name}</span>`;
    els.checklist.appendChild(row);
    rows[m.id] = row;
  }

  let toastTimer = null;

  return {
    setVisible(visible) {
      root.style.display = visible ? '' : 'none';
    },
    setPaused(paused) {
      els.pause.style.display = paused ? 'flex' : 'none';
    },
    update({ agl, speed, heading, throttle, distanceToPrimary, visitedCount, total, aircraftName, boostActive }) {
      els.altitude.textContent = `${Math.round(agl * M_TO_FT)} ft AGL`;
      els.speed.textContent = `${Math.round(speed * MS_TO_KT)} kt`;
      const h = headingLabel(heading);
      els.heading.textContent = `${String(h.deg).padStart(3, '0')}° ${h.dir}`;
      els.throttle.textContent = `${Math.round(throttle * 100)}%`;
      els.aircraft.textContent = aircraftName;
      els.boost.textContent = boostActive ? '10× ENGAGED' : 'STANDBY';
      els.boost.classList.toggle('active', boostActive);
      els.distance.textContent =
        distanceToPrimary == null
          ? '--'
          : distanceToPrimary < 1000
          ? `${Math.round(distanceToPrimary)} m`
          : `${(distanceToPrimary / 1000).toFixed(2)} km`;
      els.progress.textContent = `${visitedCount}/${total} landmarks visited`;
    },
    markVisited(marker) {
      const row = rows[marker.id];
      if (row) row.classList.add('visited');
    },
    toast(message) {
      els.toast.textContent = message;
      els.toast.classList.add('show');
      clearTimeout(toastTimer);
      toastTimer = setTimeout(() => els.toast.classList.remove('show'), 4200);
    },
  };
}

import * as THREE from 'three';

// --- Tunables -------------------------------------------------------------
const GRAVITY = -9.81;          // m/s^2, applied to Y each frame
const FIRE_COOLDOWN = 1.0;      // seconds between launches
const MISSILE_SPEED_BONUS = 60; // added on top of caller-supplied speed

// Fireball: requester asked for a much bigger, very visible burst — 5x the
// original spec (core 30 m -> 150 m, particles ~40 m -> ~200 m).
const CORE_START_RADIUS = 10;   // scaled up 5x from 2 m
const CORE_END_RADIUS = 150;    // scaled up 5x from 30 m
const CORE_DURATION = 1.4;      // seconds
const PARTICLE_COUNT = 60;
const PARTICLE_SPREAD = 200;    // radial burst distance, 5x of ~40 m
const PARTICLE_DURATION = 2.2;  // seconds
const LIGHT_COLOR = 0xff8822;
const LIGHT_INTENSITY = 40;
const LIGHT_DISTANCE = 80;
const LIGHT_DECAY = 2;
const LIGHT_FADE_TIME = 0.8;    // seconds to decay intensity to 0
const FIREBALL_LIFETIME = 2.2;  // remove everything after this age

// Color ramp white -> orange -> red -> transparent over core life.
const COLOR_STOPS = [
  { t: 0.0, color: new THREE.Color(0xffffff), opacity: 1.0 },
  { t: 0.35, color: new THREE.Color(0xffaa33), opacity: 1.0 },
  { t: 0.7, color: new THREE.Color(0xff3311), opacity: 0.85 },
  { t: 1.0, color: new THREE.Color(0xff2200), opacity: 0.0 },
];

function sampleFireballColor(t, out) {
  const clamped = Math.max(0, Math.min(1, t));
  let i = 0;
  while (i < COLOR_STOPS.length - 1 && COLOR_STOPS[i + 1].t < clamped) i++;
  const a = COLOR_STOPS[i];
  const b = COLOR_STOPS[Math.min(i + 1, COLOR_STOPS.length - 1)];
  const span = b.t - a.t || 1;
  const f = Math.max(0, Math.min(1, (clamped - a.t) / span));
  out.color.copy(a.color).lerp(b.color, f);
  out.opacity = a.opacity + (b.opacity - a.opacity) * f;
}

// --- Missile mesh ---------------------------------------------------------
let missileGeometry = null;
let missileMaterial = null;

function getMissileMesh() {
  if (!missileGeometry) {
    missileGeometry = new THREE.ConeGeometry(0.5, 3, 8);
    missileGeometry.rotateX(Math.PI / 2); // point +Z so we can align with velocity
    missileMaterial = new THREE.MeshStandardMaterial({
      color: 0xd8d8e0,
      metalness: 0.7,
      roughness: 0.35,
      emissive: 0x331100,
      emissiveIntensity: 0.4,
    });
  }
  return new THREE.Mesh(missileGeometry, missileMaterial);
}

// --- Fireball -------------------------------------------------------------
function makeRadialDirections(count) {
  const dirs = new Float32Array(count * 3);
  for (let i = 0; i < count; i++) {
    // Uniform-ish sphere directions via golden angle spiral.
    const phi = Math.acos(1 - 2 * ((i + 0.5) / count));
    const theta = Math.PI * (1 + Math.sqrt(5)) * i;
    dirs[i * 3] = Math.sin(phi) * Math.cos(theta);
    dirs[i * 3 + 1] = Math.cos(phi);
    dirs[i * 3 + 2] = Math.sin(phi) * Math.sin(theta);
  }
  return dirs;
}

function createFireball(scene, impactPoint) {
  const group = new THREE.Group();
  group.position.copy(impactPoint);

  // Core sphere: scales from CORE_START_RADIUS to CORE_END_RADIUS over CORE_DURATION.
  const coreGeo = new THREE.SphereGeometry(1, 24, 16);
  const coreMat = new THREE.MeshBasicMaterial({
    color: 0xffffff,
    transparent: true,
    opacity: 1.0,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
  });
  const core = new THREE.Mesh(coreGeo, coreMat);
  core.scale.setScalar(CORE_START_RADIUS);
  core.renderOrder = 20;
  group.add(core);

  // Particles: 60 vertices bursting radially to ~PARTICLE_SPREAD over PARTICLE_DURATION.
  const particleGeo = new THREE.BufferGeometry();
  const positions = new Float32Array(PARTICLE_COUNT * 3);
  const dirs = makeRadialDirections(PARTICLE_COUNT);
  particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  const particleMat = new THREE.PointsMaterial({
    color: 0xffbb55,
    size: 2.5,
    transparent: true,
    opacity: 1.0,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    toneMapped: false,
    sizeAttenuation: true,
  });
  const particles = new THREE.Points(particleGeo, particleMat);
  particles.frustumCulled = false;
  particles.renderOrder = 21;
  group.add(particles);

  // Light: decays to 0 over LIGHT_FADE_TIME.
  const light = new THREE.PointLight(LIGHT_COLOR, LIGHT_INTENSITY, LIGHT_DISTANCE, LIGHT_DECAY);
  group.add(light);

  scene.add(group);

  return {
    group,
    core,
    coreGeo,
    coreMat,
    particles,
    particleGeo,
    particleMat,
    dirs,
    light,
    age: 0,
  };
}

function disposeFireball(scene, fb) {
  scene.remove(fb.group);
  fb.coreGeo.dispose();
  fb.coreMat.dispose();
  fb.particleGeo.dispose();
  fb.particleMat.dispose();
}

function updateFireball(scene, fb, dt) {
  fb.age += dt;
  if (fb.age >= FIREBALL_LIFETIME) {
    disposeFireball(scene, fb);
    return false;
  }

  const coreT = Math.min(1, fb.age / CORE_DURATION);
  const radius = CORE_START_RADIUS + (CORE_END_RADIUS - CORE_START_RADIUS) * coreT;
  fb.core.scale.setScalar(radius);
  const scratch = { color: new THREE.Color(), opacity: 0 };
  sampleFireballColor(coreT, scratch);
  fb.coreMat.color.copy(scratch.color);
  fb.coreMat.opacity = scratch.opacity;

  const pT = Math.min(1, fb.age / PARTICLE_DURATION);
  const posAttr = fb.particleGeo.getAttribute('position');
  const arr = posAttr.array;
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    const d = pT * PARTICLE_SPREAD;
    arr[i * 3] = fb.dirs[i * 3] * d;
    arr[i * 3 + 1] = fb.dirs[i * 3 + 1] * d;
    arr[i * 3 + 2] = fb.dirs[i * 3 + 2] * d;
  }
  posAttr.needsUpdate = true;
  fb.particleMat.opacity = 1 - pT;

  const lT = Math.min(1, fb.age / LIGHT_FADE_TIME);
  fb.light.intensity = LIGHT_INTENSITY * (1 - lT);

  return true;
}

// --- System ---------------------------------------------------------------
export function createMissileSystem(scene, getGroundHeight) {
  const missiles = [];
  const fireballs = [];
  let lastFireTime = -Infinity;
  const clock = { now: 0 }; // accumulated simulation time

  const _forward = new THREE.Vector3();
  const _velocity = new THREE.Vector3();
  const _impact = new THREE.Vector3();

  function fire(origin, forward, speed) {
    if (clock.now - lastFireTime < FIRE_COOLDOWN) return false;
    lastFireTime = clock.now;

    const mesh = getMissileMesh();
    mesh.position.copy(origin);
    _forward.copy(forward).normalize();
    mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), _forward);
    scene.add(mesh);

    _velocity.copy(_forward).multiplyScalar(speed + MISSILE_SPEED_BONUS);
    missiles.push({ mesh, velocity: _velocity.clone() });
    return true;
  }

  function update(dt) {
    clock.now += dt;

    // Missiles: integrate gravity, move, check ground collision.
    for (let i = missiles.length - 1; i >= 0; i--) {
      const m = missiles[i];
      m.velocity.y += GRAVITY * dt;
      m.mesh.position.addScaledVector(m.velocity, dt);
      m.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), _forward.copy(m.velocity).normalize());

      const groundY = getGroundHeight(m.mesh.position.x, m.mesh.position.z);
      if (m.mesh.position.y <= groundY) {
        _impact.copy(m.mesh.position);
        _impact.y = groundY;
        scene.remove(m.mesh);
        missiles.splice(i, 1);
        fireballs.push(createFireball(scene, _impact));
      }
    }

    // Fireballs: animate and cull expired ones.
    for (let i = fireballs.length - 1; i >= 0; i--) {
      if (!updateFireball(scene, fireballs[i], dt)) {
        fireballs.splice(i, 1);
      }
    }
  }

  return { fire, update };
}
